		clickTableCell(table, 3, 0, 2);
		waitForSwing();

		Address destAddr = addr(0x01008394);
		assertEquals(destAddr, browser.getCurrentLocation().getAddress());

		runSwing(() => getProviders()[0].closeComponent());

		assertEquals(destAddr, browser.getCurrentLocation().getAddress());
	}

